//! # Quickstart Example for libmaxminddb-rs
//!
//! This example demonstrates the most common workflow:
//! 1. Defining a custom record structure for your IP data.
//! 2. Creating an in-memory MaxMind DB (MMDB) database using `Writer`.
//! 3. Inserting IP network ranges with associated structured metadata.
//! 4. Opening the database using `Reader` with zero-copy decoding.
//! 5. Looking up IP addresses and extracting strongly typed records.
//!
//! Run this example with:
//! ```bash
//! cargo run --example quickstart
//! ```

use std::error::Error;
use std::net::IpAddr;

use libmaxminddb_rs::{MetadataBuilder, MmdbDecode, MmdbEncode, Reader, Writer};

/// Record structure used to store and retrieve geolocation data.
///
/// By deriving both `MmdbEncode` and `MmdbDecode`, this struct can be
/// serialized into the MMDB data section and deserialized directly back.
///
/// Notice the use of borrowed string slices (`&'a str`):
/// during lookup, string data points directly into the database bytes,
/// completely avoiding heap allocations!
#[derive(Debug, PartialEq, MmdbEncode, MmdbDecode)]
struct CityRecord<'a> {
    country: &'a str,
    city: &'a str,
    postal_code: Option<&'a str>,
    latitude: f64,
    longitude: f64,
}

fn main() -> Result<(), Box<dyn Error>> {
    println!("=== libmaxminddb-rs Quickstart Example ===\n");

    // -----------------------------------------------------------------------
    // Step 1: Build the MMDB database in memory
    // -----------------------------------------------------------------------
    println!("1. Initializing database metadata...");
    let metadata = MetadataBuilder::new()
        .database_type("Quickstart-City-DB")
        .ip_version(4)
        .language("en")
        .language("fr")
        .description("en", "Quickstart geolocation example database")
        .description("fr", "Exemple de base de données de géolocalisation")
        .build()?;

    let mut writer = Writer::with_metadata(metadata);

    // -----------------------------------------------------------------------
    // Step 2: Insert IP networks with associated records
    // -----------------------------------------------------------------------
    println!("2. Inserting IP ranges...");

    // Paris, France: 203.0.113.0/24
    writer.insert_encoded(
        "203.0.113.0/24".parse()?,
        &CityRecord {
            country: "FR",
            city: "Paris",
            postal_code: Some("75001"),
            latitude: 48.8566,
            longitude: 2.3522,
        },
    )?;

    // Tokyo, Japan: 198.51.100.0/24
    writer.insert_encoded(
        "198.51.100.0/24".parse()?,
        &CityRecord {
            country: "JP",
            city: "Tokyo",
            postal_code: Some("100-0001"),
            latitude: 35.6762,
            longitude: 139.6503,
        },
    )?;

    // Finalize the database into a contiguous byte buffer.
    // In production, you can also use `writer.write_to_file("output.mmdb")`.
    let mmdb_bytes: Vec<u8> = writer.finish()?;
    println!(
        "   Database generated in memory (size: {} bytes).\n",
        mmdb_bytes.len()
    );

    // -----------------------------------------------------------------------
    // Step 3: Open the database with Reader
    // -----------------------------------------------------------------------
    println!("3. Opening database with Reader...");
    let reader = Reader::from_bytes(&mmdb_bytes)?;

    // -----------------------------------------------------------------------
    // Step 4: Perform zero-copy lookups
    // -----------------------------------------------------------------------
    println!("4. Performing lookups:\n");

    let test_ips: &[(&str, &str)] = &[
        ("203.0.113.42", "Paris, France subnet"),
        ("198.51.100.10", "Tokyo, Japan subnet"),
    ];

    for &(ip_str, note) in test_ips {
        let ip: IpAddr = ip_str.parse()?;

        // Perform zero-copy borrowed lookup:
        // `lookup_borrowed` yields a struct whose string slices reference
        // `mmdb_bytes` directly, with zero allocations!
        let record: CityRecord<'_> = reader.lookup_borrowed(ip)?;

        println!("   IP: {} ({})", ip, note);
        println!("   ↳ Country     : {}", record.country);
        println!("   ↳ City        : {}", record.city);
        println!("   ↳ Postal Code : {:?}", record.postal_code);
        println!(
            "   ↳ Coordinates : ({:.4}, {:.4})\n",
            record.latitude, record.longitude
        );
    }

    // -----------------------------------------------------------------------
    // Step 5: Handling unknown / unmapped IP addresses
    // -----------------------------------------------------------------------
    let unmapped_ip: IpAddr = "192.0.2.1".parse()?;
    match reader.lookup_value(unmapped_ip) {
        Ok(value) => println!("   Unexpected record for {}: {:?}", unmapped_ip, value),
        Err(err) => println!(
            "5. Looked up unmapped IP {} -> Expected error: {}\n",
            unmapped_ip, err
        ),
    }

    println!("Quickstart example completed successfully!");
    Ok(())
}

//! Run with `cargo run --example editor_merge`.

use std::sync::Arc;

use libmaxminddb_rs::{
    Editor, MergeStrategy, MetadataBuilder, MmdbDecode, MmdbEncode, Reader, ReloadableReader,
    Writer,
};

#[derive(Debug, MmdbEncode, MmdbDecode)]
struct Record<'a> {
    country: &'a str,
    score: u32,
}

#[derive(MmdbEncode)]
struct Patch {
    score: u32,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let network = "198.51.100.0/24".parse()?;
    let ip = "198.51.100.7".parse()?;
    let metadata = MetadataBuilder::new().ip_version(4).build()?;
    let mut writer = Writer::with_metadata(metadata);
    writer.insert_encoded(
        network,
        &Record {
            country: "FR",
            score: 1,
        },
    )?;

    // Transfer ownership without retaining an extra Arc to the old database.
    let database = ReloadableReader::new(Reader::from_vec(writer.finish()?)?);
    {
        let guard = database.load();
        let record: Record<'_> = guard.lookup_borrowed(ip)?;
        println!("Before update: {record:?}");
    } // Borrowed fields and their guard are dropped before publication.

    let mut editor = Editor::from_reader(database.snapshot());
    // Weak observes destruction without keeping the old Reader alive.
    let old_lifetime = Arc::downgrade(editor.source_reader());
    editor.update_value(network, &Patch { score: 42 }, MergeStrategy::DeepMerge)?;

    // Rebuild, then publish atomically. A stale editor would return false.
    assert!(database.commit(editor)?, "Unexpected publication conflict");
    assert!(old_lifetime.upgrade().is_none());
    drop(old_lifetime);
    println!("Committed: the old Reader and its owned buffers were released.");

    let guard = database.load();
    let record: Record<'_> = guard.lookup_borrowed(ip)?;
    assert_eq!((record.country, record.score), ("FR", 42));
    println!("After DeepMerge: {record:?}");
    Ok(())
}

//! Run with `cargo run --example concurrent_editor`.

use std::sync::{Arc, Barrier};

use libmaxminddb_rs::{
    Editor, MergeStrategy, MetadataBuilder, Reader, ReloadableReader, Value, ValueRef, Writer,
};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut writer = Writer::with_metadata(MetadataBuilder::new().ip_version(4).build()?);
    writer.insert_value("10.0.0.0/8".parse()?, Value::Uint32(0))?;
    let initial = Arc::new(Reader::from_vec(writer.finish()?)?);
    let database = ReloadableReader::new(Arc::clone(&initial));
    let barrier = Barrier::new(5);
    let ip = "10.1.2.3".parse()?;
    let network = "10.0.0.0/8".parse()?;

    println!("[setup] Created generation 0 for {network}; lookup address: {ip}.");
    println!("[setup] The container and original snapshot share one immutable Reader.");
    println!("[setup] Four readers will run alongside one writer.");
    println!("[setup] Console messages from different threads may interleave.");

    std::thread::scope(|scope| {
        let mut readers = Vec::new();
        for reader_id in 0..4 {
            let database = &database;
            let barrier = &barrier;
            readers.push(scope.spawn(move || {
                println!("[reader {reader_id}] Ready; waiting at the start barrier.");
                barrier.wait();
                for _ in 0..10_000 {
                    // Keep the guard alive for the whole query/batch, including
                    // any values borrowing strings or bytes from its reader.
                    let pinned = database.load();
                    let first = pinned.lookup_value(ip).unwrap();
                    assert_eq!(first, pinned.lookup_value(ip).unwrap());
                    assert!(matches!(first, ValueRef::Uint32(0..=20)));
                }
                println!("[reader {reader_id}] Finished 10,000 consistent guarded queries.");
            }));
        }
        barrier.wait();
        println!("[writer] Starting edits while reader threads perform their queries.");
        for generation in 1..=20 {
            // Share the current reader and PreparedTree, without copying bytes.
            let source = database.snapshot();
            let mut editor = Editor::from_reader(source);
            editor.update_value(network, Value::Uint32(generation), MergeStrategy::Replace)?;
            println!("[writer] Staged generation {generation} in a private editor overlay.");
            println!("[writer] Source bytes and the prepared tree remain unchanged.");
            // Rebuild outside publication, then CAS against the source Arc.
            // Multiple writers should retry from a fresh snapshot on conflict.
            assert!(database.commit(editor)?);
            println!("[writer] Rebuilt, prepared and atomically published {generation}.");
            println!("[writer] Existing guards keep their version; new loads see this one.");
        }
        println!("[writer] All 20 generations published; waiting for reader threads.");
        for worker in readers {
            worker.join().expect("reader thread panicked");
        }
        Ok::<(), libmaxminddb_rs::Error>(())
    })?;

    assert_eq!(initial.lookup_value(ip)?, ValueRef::Uint32(0));
    assert_eq!(database.load().lookup_value(ip)?, ValueRef::Uint32(20));
    println!("[verify] The original snapshot still returns generation 0.");
    println!("[verify] The active reader now returns generation 20.");
    println!("[done] All concurrent reads and edits completed successfully.");
    Ok(())
}
